  <style>
    :root {
      --primary: #1B1464;
      --primary-light: #2a1f8a;
      --accent: #FFD930;
      --accent-dark: #e6c22e;
      --white: #FFFFFF;
      --gray-50: #F8F9FA;
      --gray-100: #F1F3F5;
      --gray-200: #E9ECEF;
      --gray-300: #DEE2E6;
      --gray-400: #CED4DA;
      --gray-500: #ADB5BD;
      --gray-600: #868E96;
      --gray-700: #495057;
      --gray-800: #343A40;
      --gray-900: #212529;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow: 0 4px 6px rgba(0,0,0,0.07);
      --shadow-md: 0 6px 16px rgba(0,0,0,0.1);
      --shadow-lg: 0 10px 40px rgba(0,0,0,0.12);
      --radius-sm: 8px;
      --radius: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
    }

    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      color: var(--gray-800);
      background: var(--white);
      line-height: 1.6;
      font-size: 16px;
      -webkit-font-smoothing: antialiased;
    }

    a {
      text-decoration: none;
      color: inherit;
    }

    img {
      max-width: 100%;
      height: auto;
    }

    /* Header */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 100;
      background: var(--white);
      box-shadow: var(--shadow-sm);
      transition: box-shadow 0.2s;
    }

    .header.scrolled {
      box-shadow: var(--shadow);
    }

    .header-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
      height: 72px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .logo {
      font-size: 24px;
      font-weight: 800;
      color: var(--primary);
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .logo-icon {
      width: 36px;
      height: 36px;
      background: var(--primary);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg {
      width: 24px;
      height: 24px;
      color: var(--accent);
    }

    .nav {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 28px;
      list-style: none;
    }

    .nav-links a {
      font-weight: 500;
      color: var(--gray-700);
      transition: color 0.2s;
      font-size: 15px;
    }

    .nav-links a:hover {
      color: var(--primary);
    }

    .nav-buttons {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      padding: 10px 20px;
      border-radius: var(--radius-sm);
      font-weight: 600;
      font-size: 14px;
      transition: all 0.2s;
      cursor: pointer;
      border: none;
    }

    .btn-ghost {
      background: transparent;
      color: var(--gray-700);
    }

    .btn-ghost:hover {
      background: var(--gray-100);
      color: var(--primary);
    }

    .btn-primary {
      background: var(--primary);
      color: var(--white);
    }

    .btn-primary:hover {
      background: var(--primary-light);
      transform: translateY(-1px);
    }

    .btn-accent {
      background: var(--accent);
      color: var(--primary);
    }

    .btn-accent:hover {
      background: var(--accent-dark);
      transform: translateY(-1px);
    }

    /* Mobile Menu */
    .mobile-toggle {
      display: none;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
    }

    .mobile-toggle svg {
      width: 24px;
      height: 24px;
      color: var(--gray-700);
    }

    .mobile-menu {
      display: none;
      position: fixed;
      top: 0;
      right: 0;
      bottom: 0;
      width: 280px;
      background: var(--white);
      box-shadow: var(--shadow-lg);
      z-index: 200;
      transform: translateX(100%);
      transition: transform 0.3s ease;
    }

    .mobile-menu.open {
      transform: translateX(0);
    }

    .mobile-menu-overlay {
      display: none;
      position: fixed;
      inset: 0;
      background: rgba(0,0,0,0.5);
      z-index: 150;
      opacity: 0;
      transition: opacity 0.3s;
    }

    .mobile-menu-overlay.open {
      opacity: 1;
    }

    .mobile-menu-header {
      padding: 20px 24px;
      border-bottom: 1px solid var(--gray-200);
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .mobile-menu-close {
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
    }

    .mobile-menu-close svg {
      width: 24px;
      height: 24px;
    }

    .mobile-menu-nav {
      padding: 24px;
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .mobile-menu-nav a {
      display: block;
      padding: 12px 0;
      font-weight: 500;
      font-size: 16px;
      color: var(--gray-700);
      border-bottom: 1px solid var(--gray-100);
    }

    .mobile-menu-nav a:hover {
      color: var(--primary);
    }

    .mobile-menu-buttons {
      padding: 24px;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .mobile-menu-buttons .btn {
      width: 100%;
      padding: 14px;
    }

    /* Hero */
    .hero {
      padding: 140px 24px 80px;
      background: linear-gradient(180deg, var(--gray-50) 0%, var(--white) 100%);
      text-align: center;
    }

    .hero-content {
      max-width: 800px;
      margin: 0 auto;
    }

    .hero h1 {
      font-size: clamp(36px, 5vw, 56px);
      font-weight: 800;
      color: var(--primary);
      line-height: 1.1;
      margin-bottom: 20px;
    }

    .hero p {
      font-size: 18px;
      color: var(--gray-600);
      max-width: 600px;
      margin: 0 auto 32px;
      line-height: 1.7;
    }

    /* Search Bar */
    .search-container {
      max-width: 900px;
      margin: 0 auto;
    }

    .search-form {
      background: var(--white);
      border-radius: var(--radius-xl);
      box-shadow: var(--shadow-lg);
      padding: 8px;
      display: grid;
      grid-template-columns: 1fr 1fr auto;
      gap: 8px;
    }

    .search-field {
      position: relative;
    }

    .search-field input,
    .search-field select {
      width: 100%;
      padding: 16px 16px 16px 48px;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius);
      font-size: 16px;
      font-family: inherit;
      background: var(--white);
      transition: all 0.2s;
      outline: none;
    }

    .search-field input:focus,
    .search-field select:focus {
      border-color: var(--primary);
      box-shadow: 0 0 0 4px rgba(27, 20, 100, 0.1);
    }

    .search-field-icon {
      position: absolute;
      left: 16px;
      top: 50%;
      transform: translateY(-50%);
      width: 20px;
      height: 20px;
      color: var(--gray-400);
    }

    .search-field select {
      appearance: none;
      cursor: pointer;
      padding-left: 16px;
    }

    .search-submit {
      background: var(--accent);
      border: none;
      border-radius: var(--radius);
      padding: 16px 32px;
      font-weight: 700;
      font-size: 16px;
      color: var(--primary);
      cursor: pointer;
      transition: all 0.2s;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
    }

    .search-submit:hover {
      background: var(--accent-dark);
      transform: translateY(-1px);
    }

    .search-submit svg {
      width: 20px;
      height: 20px;
    }

    /* Autocomplete Dropdown */
    .autocomplete-dropdown {
      position: absolute;
      top: calc(100% + 4px);
      left: 0;
      right: 0;
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      box-shadow: var(--shadow-md);
      max-height: 300px;
      overflow-y: auto;
      z-index: 50;
      display: none;
    }

    .autocomplete-dropdown.active {
      display: block;
    }

    .autocomplete-item {
      padding: 12px 16px;
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: 12px;
      border-bottom: 1px solid var(--gray-100);
      transition: background 0.15s;
    }

    .autocomplete-item:last-child {
      border-bottom: none;
    }

    .autocomplete-item:hover,
    .autocomplete-item.selected {
      background: var(--gray-50);
    }

    .autocomplete-item svg {
      width: 18px;
      height: 18px;
      color: var(--gray-400);
    }

    .autocomplete-item-text {
      flex: 1;
    }

    .autocomplete-item-title {
      font-weight: 500;
      color: var(--gray-800);
    }

    .autocomplete-item-subtitle {
      font-size: 13px;
      color: var(--gray-500);
    }

    /* Specialties */
    .specialties {
      padding: 80px 24px;
      background: var(--white);
    }

    .section-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .section-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .section-header h2 {
      font-size: 32px;
      font-weight: 700;
      color: var(--primary);
      margin-bottom: 12px;
    }

    .section-header p {
      font-size: 18px;
      color: var(--gray-600);
    }

    .specialty-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
      gap: 20px;
    }

    .specialty-card {
      background: var(--gray-50);
      border-radius: var(--radius-lg);
      padding: 28px 20px;
      text-align: center;
      cursor: pointer;
      transition: all 0.25s ease;
      border: 2px solid transparent;
    }

    .specialty-card:hover {
      background: var(--white);
      border-color: var(--primary);
      transform: translateY(-4px);
      box-shadow: var(--shadow-md);
    }

    .specialty-icon {
      width: 64px;
      height: 64px;
      background: var(--white);
      border-radius: var(--radius);
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 16px;
      box-shadow: var(--shadow-sm);
    }

    .specialty-icon svg {
      width: 32px;
      height: 32px;
      color: var(--primary);
    }

    .specialty-card h3 {
      font-size: 16px;
      font-weight: 600;
      color: var(--gray-800);
      margin-bottom: 6px;
    }

    .specialty-card p {
      font-size: 13px;
      color: var(--gray-500);
      line-height: 1.4;
    }

    /* Stats */
    .stats {
      padding: 60px 24px;
      background: var(--primary);
    }

    .stats-inner {
      max-width: 1000px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
    }

    .stat-item {
      text-align: center;
    }

    .stat-value {
      font-size: 40px;
      font-weight: 800;
      color: var(--accent);
      line-height: 1;
      margin-bottom: 8px;
    }

    .stat-label {
      font-size: 15px;
      color: rgba(255,255,255,0.85);
      font-weight: 500;
    }

    /* How It Works */
    .how-it-works {
      padding: 80px 24px;
      background: var(--gray-50);
    }

    .steps {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 40px;
      position: relative;
    }

    .steps::before {
      content: '';
      position: absolute;
      top: 40px;
      left: calc(16.67% + 20px);
      right: calc(16.67% + 20px);
      height: 2px;
      background: linear-gradient(90deg, var(--gray-300) 50%, transparent 50%);
      background-size: 40px 2px;
    }

    .step {
      text-align: center;
      position: relative;
    }

    .step-number {
      width: 80px;
      height: 80px;
      background: var(--white);
      border: 3px solid var(--primary);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 24px;
      position: relative;
      z-index: 1;
    }

    .step-number span {
      font-size: 32px;
      font-weight: 800;
      color: var(--primary);
    }

    .step h3 {
      font-size: 20px;
      font-weight: 700;
      color: var(--primary);
      margin-bottom: 12px;
    }

    .step p {
      font-size: 15px;
      color: var(--gray-600);
      line-height: 1.6;
    }

    /* Testimonials */
    .testimonials {
      padding: 80px 24px;
      background: var(--white);
    }

    .testimonial-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .testimonial-card {
      background: var(--gray-50);
      border-radius: var(--radius-lg);
      padding: 32px;
      position: relative;
    }

    .testimonial-quote {
      font-size: 48px;
      color: var(--primary);
      opacity: 0.15;
      position: absolute;
      top: 20px;
      left: 24px;
      line-height: 1;
    }

    .testimonial-text {
      font-size: 16px;
      color: var(--gray-700);
      line-height: 1.7;
      margin-bottom: 20px;
      font-style: italic;
    }

    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .testimonial-avatar {
      width: 48px;
      height: 48px;
      background: var(--primary);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
      font-weight: 700;
      font-size: 18px;
    }

    .testimonial-info h4 {
      font-size: 15px;
      font-weight: 600;
      color: var(--gray-800);
    }

    .testimonial-info span {
      font-size: 13px;
      color: var(--gray-500);
    }

    /* Mobile App Promo */
    .app-promo {
      padding: 80px 24px;
      background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
      color: var(--white);
    }

    .app-promo-inner {
      max-width: 1000px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
      align-items: center;
    }

    .app-content h2 {
      font-size: 36px;
      font-weight: 800;
      margin-bottom: 16px;
      line-height: 1.2;
    }

    .app-content p {
      font-size: 18px;
      opacity: 0.9;
      margin-bottom: 28px;
      line-height: 1.6;
    }

    .app-buttons {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
    }

    .store-btn {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      background: var(--white);
      color: var(--primary);
      padding: 12px 20px;
      border-radius: var(--radius);
      font-weight: 600;
      font-size: 14px;
      transition: all 0.2s;
    }

    .store-btn:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow-md);
    }

    .store-btn svg {
      width: 24px;
      height: 24px;
    }

    .store-btn span {
      text-align: left;
    }

    .store-btn small {
      display: block;
      font-size: 10px;
      font-weight: 400;
      opacity: 0.7;
    }

    .app-features {
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    .app-feature {
      display: flex;
      align-items: center;
      gap: 16px;
      background: rgba(255,255,255,0.1);
      padding: 16px 20px;
      border-radius: var(--radius);
    }

    .app-feature svg {
      width: 24px;
      height: 24px;
      color: var(--accent);
      flex-shrink: 0;
    }

    .app-feature span {
      font-size: 15px;
      font-weight: 500;
    }

    /* Footer */
    .footer {
      background: var(--gray-900);
      color: var(--gray-400);
      padding: 60px 24px 30px;
    }

    .footer-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 2fr repeat(3, 1fr);
      gap: 48px;
      margin-bottom: 48px;
    }

    .footer-brand {
      max-width: 280px;
    }

    .footer-brand .logo {
      color: var(--white);
      margin-bottom: 16px;
    }

    .footer-brand p {
      font-size: 14px;
      line-height: 1.7;
    }

    .footer-col h4 {
      color: var(--white);
      font-size: 14px;
      font-weight: 600;
      margin-bottom: 20px;
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }

    .footer-col ul {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .footer-col a {
      font-size: 14px;
      transition: color 0.2s;
    }

    .footer-col a:hover {
      color: var(--white);
    }

    .footer-bottom {
      border-top: 1px solid var(--gray-800);
      padding-top: 24px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 16px;
    }

    .footer-bottom p {
      font-size: 13px;
    }

    .footer-legal {
      display: flex;
      gap: 24px;
    }

    .footer-legal a {
      font-size: 13px;
    }

    /* Responsive */
    @media (max-width: 1024px) {
      .search-form {
        grid-template-columns: 1fr;
      }

      .steps {
        grid-template-columns: 1fr;
        gap: 48px;
      }

      .steps::before {
        display: none;
      }

      .testimonial-grid {
        grid-template-columns: 1fr;
        max-width: 600px;
        margin: 0 auto;
      }

      .app-promo-inner {
        grid-template-columns: 1fr;
        text-align: center;
      }

      .app-buttons {
        justify-content: center;
      }
    }

    @media (max-width: 768px) {
