    const suggestions = [
      { title: 'Primary Care', subtitle: 'General health checkups and preventive care', type: 'specialty' },
      { title: 'Dentist', subtitle: 'Oral health, cleanings, and dental care', type: 'specialty' },
      { title: 'Dermatologist', subtitle: 'Skin conditions, acne, and cosmetics', type: 'specialty' },
      { title: 'Psychiatrist', subtitle: 'Mental health and medication management', type: 'specialty' },
      { title: 'Eye Doctor', subtitle: 'Vision exams and eye health', type: 'specialty' },
      { title: 'Orthopedic Surgeon', subtitle: 'Joints, bones, and sports injuries', type: 'specialty' },
